package com.profa.messaging;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity @Table(name="messages")public class Message{@Id@GeneratedValue(strategy=GenerationType.UUID)UUID id;UUID conversationId;UUID senderId;@Column(length=5000)String body;String type="TEXT";boolean read=false;Instant createdAt=Instant.now();public UUID getId(){return id;}public UUID getConversationId(){return conversationId;}public void setConversationId(UUID v){conversationId=v;}public UUID getSenderId(){return senderId;}public void setSenderId(UUID v){senderId=v;}public String getBody(){return body;}public void setBody(String v){body=v;}public String getType(){return type;}public void setType(String v){type=v;}public boolean isRead(){return read;}public void setRead(boolean v){read=v;}}